{
  "records": [
    {
      "topic": "Laser drilling of steel using pulsed laser",
      "kind": "problem",
      "blockIds": ["B21"],
      "givens": [
        {
          "name": "average pulse energy",
          "value": "40",
          "unit": "J",
          "sourceText": "nâng lự trung binh là 40 J",
          "blockId": "B21"
        },
        {
          "name": "laser beam radius",
          "value": "1,2",
          "unit": "mm",
          "sourceText": "đường kính d = 1,2 mm",
          "blockId": "B21"
        },
        {
          "name": "initial steel temperature",
          "value": "35",
          "unit": "°C",
          "sourceText": "tẩm thép có nhiệt độ trước khi khoan an là t1 = 35°C",
          "blockId": "B21"
        },
        {
          "name": "steel density",
          "value": "7800",
          "unit": "kg/m^3",
          "sourceText": "khối lượng riêng của tẩm thép là ρ = 7800 kg/m^3",
          "blockId": "B21"
        },
        {
          "name": "steel specific heat",
          "value": "440",
          "unit": "J/(kg·K)",
          "sourceText": "nhiệt dung riêng của tẩm thép là c = 440 J/(kg.K)",
          "blockId": "B21"
        },
        {
          "name": "steel latent heat of fusion",
          "value": "270",
          "unit": "kJ/kg",
          "sourceText": "nhiệt nóng chảy riêng của tẩm thép là λ = 270 kJ/kg",
          "blockId": "B21"
        },
        {
          "name": "steel melting temperature",
          "value": "1535",
          "unit": "°C",
          "sourceText": "nhiệt độ nóng chảy của thép là t = 1535°C",
          "blockId": "B21"
        },
        {
          "name": "drilling time",
          "value": "1,845",
          "unit": "s",
          "sourceText": "thời gian khoan trong tẩm thép là 1,845 s",
          "blockId": "B21"
        }
      ],
      "conditions": [
        "Laser pulses are repeated during the drilling interval of 1,845 s."
      ],
      "relationships": [
        "Q = m·c·ΔT (sensible heat)",
        "Q = m·λ (latent heat of fusion)",
        "Energy supplied per pulse multiplied by number of pulses equals total energy absorbed."
      ]
    },
    {
      "topic": "Therapeutic hypothermia using ice bath for stroke patient",
      "kind": "problem",
      "blockIds": ["B23"],
      "givens": [
        {
          "name": "body specific heat",
          "value": "3480",
          "unit": "J/(kg·K)",
          "sourceText": "nhiệt dung riêng của cơ thể người là 3480 J/kg.K",
          "blockId": "B23"
        },
        {
          "name": "ice latent heat of fusion",
          "value": "334.10³",
          "unit": "J/kg",
          "sourceText": "nhiệt nóng chảy riêng của nước đá là 334.10³ J/kg",
          "blockId": "B23"
        },
        {
          "name": "normal body temperature",
          "value": "37",
          "unit": "°C",
          "sourceText": "xem như nhiệt độ bình thường của cơ thể người là 37°C",
          "blockId": "B23"
        },
        {
          "name": "target body temperature",
          "value": "32",
          "unit": "°C",
          "sourceText": "bệnh nhân được làm mát cho đến khi nhiệt độ bên trong của họ đạt tới nhiệt độ 32°C",
          "blockId": "B23"
        },
        {
          "name": "patient mass",
          "value": "70,0",
          "unit": "kg",
          "sourceText": "đối với một bệnh nhân nặng 70,0 kg",
          "blockId": "B23"
        }
      ],
      "conditions": [
        "Ice remains at 0°C throughout the cooling process."
      ],
      "relationships": [
        "Q_body = m_body·c_body·(T_initial - T_target)",
        "Q_ice = m_ice·λ_ice (melting of ice absorbs heat)",
        "Heat lost by body equals heat absorbed by melting ice."
      ]
    },
    {
      "topic": "Equilibrium of ice‑water mixture",
      "kind": "problem",
      "blockIds": ["B24"],
      "givens": [
        {
          "name": "mass of ice",
          "value": "1",
          "unit": "g",
          "sourceText": "1 g nước đá được ở 0°C",
          "blockId": "B24"
        },
        {
          "name": "mass of water",
          "value": "1",
          "unit": "g",
          "sourceText": "được vào một nhiệt lượng kế chứa 1 g nước ở 40°C",
          "blockId": "B24"
        },
        {
          "name": "initial ice temperature",
          "value": "0",
          "unit": "°C",
          "sourceText": "1 g nước đá được ở 0°C",
          "blockId": "B24"
        },
        {
          "name": "initial water temperature",
          "value": "40",
          "unit": "°C",
          "sourceText": "1 g nước ở 40°C",
          "blockId": "B24"
        },
        {
          "name": "latent heat of fusion of ice",
          "value": "3,36.10⁵",
          "unit": "J/kg",
          "sourceText": "nhiệt nóng chảy riêng của nước đá là 3,36.10⁵ J/kg",
          "blockId": "B24"
        },
        {
          "name": "specific heat of water",
          "value": "4200",
          "unit": "J/(kg·K)",
          "sourceText": "nhiệt dung riêng của nước là 4200 J/kg.K",
          "blockId": "B24"
        }
      ],
      "conditions": [
        "Neglect heat capacity of the calorimeter."
      ],
      "relationships": [
        "Q = m·c·ΔT for cooling water",
        "Q = m·λ for melting ice",
        "Energy conservation: heat lost by water = heat gained by ice (sensible + latent)."
      ]
    }
  ],
  "excluded": [
    {
      "blockId": "B22",
      "reason": "duplicate description without additional quantitative data"
    }
  ]
}
